messageHandlers.script:
# when user is modifying the binding and before user saves the binding,
# need to update it here (in case breakpoint container switches between
# lg and sm when they are in the middle of configuring a new binding)
binding = payload['binding']	

# binding removed on associated data property
if 'noBinding' in binding.keys():
	self.view.custom.alarmProp = {}
else:
	propName = binding['propName']
	propVal = binding['propVal']

	self.view.custom.alarmProp = {propName:propVal}
